1) ESLint rule implementing story file reference validation
- File: src/rules/valid-story-reference.ts
- Tied to story and requirements via JSDoc:
  /**
   * Rule to validate @story annotation references refer to existing story files
   * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
   * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
   * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
   * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
   */
- Uses context.cwd (with process.cwd fallback) and configurable options, matching Implementation Notes (context object, project root resolution, options):
  create(context: Rule.RuleContext) {
    const cwd = (context as any).cwd ?? process.cwd();
    const opts = context.options[0] as {
      storyDirectories?: string[];
      allowAbsolutePaths?: boolean;
      requireStoryExtension?: boolean;
    } | undefined;
    const storyDirs = opts?.storyDirectories || defaultStoryDirs; // default ["docs/stories","stories"]
    const allowAbsolute = opts?.allowAbsolutePaths || false;
    const requireExt = opts?.requireStoryExtension !== false;
    ...
  }
- Annotation parsing and delegation (REQ-ANNOTATION-VALIDATION):
  function handleComment({ commentNode, context, cwd, storyDirs, allowAbsolute, requireExt }): void {
    const lines = commentNode.value
      .split(/\r?\n/)
      .map((l: string) => l.replace(/^[^@]*/, "").trim());
    for (const line of lines) {
      if (line.startsWith("@story")) {
        validateStoryPath({ line, commentNode, context, cwd, storyDirs, allowAbsolute, requireExt });
      }
    }
  }
- Story path extraction (REQ-ANNOTATION-VALIDATION):
  function validateStoryPath(opts: { line: string; ... }): void {
    const parts = line.split(/\s+/);
    const storyPath = parts[1];
    if (!storyPath) return;
    processStoryPath({ storyPath, ... });
  }
- Security checks and invalidPath reporting (REQ-SECURITY-VALIDATION, REQ-PROJECT-BOUNDARY):
  const securityOk = performSecurityValidations({ storyPath, commentNode, context, cwd, allowAbsolute, reportInvalidPath });
  if (!securityOk) { return; }
- Extension enforcement (Core Functionality: .story.md):
  if (requireExt && !hasValidExtension(storyPath)) {
    context.report({ node: commentNode, messageId: "invalidExtension", data: { path: storyPath } });
    return;
  }
- Existence and filesystem error handling (REQ-FILE-EXISTENCE, REQ-ERROR-HANDLING, REQ-PROJECT-BOUNDARY, REQ-CONFIGURABLE-PATHS):
  function reportExistenceProblems({ storyPath, commentNode, context, cwd, storyDirs }): void {
    const result = normalizeStoryPath(storyPath, cwd, storyDirs);
    const existenceResult = result.existence;
    const candidates = result.candidates || [];

    const invalidByBoundary = handleProjectBoundaryForExistence({
      storyPath,
      commentNode,
      context,
      cwd,
      candidates,
      existenceResult,
      reportInvalidPath,
    });

    if (invalidByBoundary) return;
    reportExistenceStatus(existenceResult, storyPath, commentNode, context);
  }
- Detailed differentiation between missing files and filesystem errors (REQ-ERROR-HANDLING):
  function reportExistenceStatus(existenceResult, storyPath, commentNode, context): void {
    if (!existenceResult || existenceResult.status === "exists") return;

    if (existenceResult.status === "missing") {
      context.report({ node: commentNode, messageId: "fileMissing", data: { path: storyPath } });
      return;
    }

    if (existenceResult.status === "fs-error") {
      const rawError = existenceResult.error;
      let errorMessage: string;
      if (rawError == null) errorMessage = "Unknown filesystem error";
      else if (rawError instanceof Error) errorMessage = rawError.message;
      else errorMessage = String(rawError);

      context.report({
        node: commentNode,
        messageId: "fileAccessError",
        data: { path: storyPath, error: errorMessage },
      });
    }
  }
- User-facing error messages (User Experience):
  messages: {
    fileMissing: "Story file '{{path}}' not found",
    invalidExtension: "Invalid story file extension for '{{path}}', expected '.story.md'",
    invalidPath: "Invalid story path '{{path}}'",
    fileAccessError: "Could not validate story file '{{path}}' due to a filesystem error: {{error}}. Please check file existence and permissions.",
  }

2) Security and project-boundary helpers
- File: src/rules/helpers/valid-story-reference-helpers.ts
- Explicit story and requirement tags:
  * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
  * @req REQ-PROJECT-BOUNDARY, REQ-SECURITY-VALIDATION, REQ-CONFIGURABLE-PATHS
- Candidate boundary analysis (REQ-PROJECT-BOUNDARY):
  export function analyzeCandidateBoundaries(candidates: string[], cwd: string) {
    let hasInProjectCandidate = false;
    let hasOutOfProjectCandidate = false;
    for (const candidate of candidates) {
      const boundary = enforceProjectBoundary(candidate, cwd);
      if (boundary.isWithinProject) hasInProjectCandidate = true;
      else hasOutOfProjectCandidate = true;
    }
    return { hasInProjectCandidate, hasOutOfProjectCandidate };
  }
- Boundary enforcement in existence phase, rejecting purely out-of-project references as invalidPath (REQ-PROJECT-BOUNDARY, REQ-CONFIGURABLE-PATHS):
  export function handleProjectBoundaryForExistence({ ... }: HandleBoundaryOptions): boolean {
    if (candidates.length > 0) {
      const { hasInProjectCandidate, hasOutOfProjectCandidate } = analyzeCandidateBoundaries(candidates, cwd);
      if (hasOutOfProjectCandidate && !hasInProjectCandidate) {
        reportInvalidPath({ storyPath, commentNode, context });
        return true;
      }
    }
    if (existenceResult && existenceResult.status === "exists" && existenceResult.matchedPath) {
      const boundary = enforceProjectBoundary(existenceResult.matchedPath, cwd);
      if (!boundary.isWithinProject) {
        reportInvalidPath({ storyPath, commentNode, context });
        return true;
      }
    }
    return false;
  }
- Security validations (REQ-SECURITY-VALIDATION):
  export function performSecurityValidations({ storyPath, commentNode, context, cwd, allowAbsolute, reportInvalidPath }: SecurityValidationOptions): boolean {
    if (path.isAbsolute(storyPath)) {
      if (!allowAbsolute) {
        reportInvalidPath({ storyPath, commentNode, context });
        return false;
      }
    }
    const containsTraversal = storyPath.includes("..") || /\\|\//.test(storyPath);
    if (containsTraversal) {
      const full = path.resolve(cwd, path.normalize(storyPath));
      if (!full.startsWith(cwd + path.sep)) {
        reportInvalidPath({ storyPath, commentNode, context });
        return false;
      }
    }
    return true;
  }

3) Path resolution, caching, existence and security utilities
- File: src/utils/storyReferenceUtils.ts
- Top-level JSDoc ties to story and multiple requirements:
  * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
  * @req REQ-PATH-RESOLUTION, REQ-FILE-EXISTENCE, REQ-SECURITY-VALIDATION, REQ-ERROR-HANDLING, REQ-PERFORMANCE-OPTIMIZATION, REQ-PROJECT-BOUNDARY
- Path resolution and candidate building (REQ-PATH-RESOLUTION, REQ-CONFIGURABLE-PATHS):
  export function buildStoryCandidates(storyPath: string, cwd: string, storyDirs: string[]): string[] {
    const candidates: string[] = [];
    if (storyPath.startsWith("./") || storyPath.startsWith("../")) {
      candidates.push(path.resolve(cwd, storyPath));
    } else {
      candidates.push(path.resolve(cwd, storyPath));
      for (const dir of storyDirs) {
        candidates.push(path.resolve(cwd, dir, path.basename(storyPath)));
      }
    }
    return candidates;
  }
- Caching of filesystem checks (REQ-PERFORMANCE-OPTIMIZATION):
  const fileExistStatusCache = new Map();
  function checkSingleCandidate(candidate: string): StoryPathCheckResult {
    const cached = fileExistStatusCache.get(candidate);
    if (cached) return cached;
    try {
      const exists = fs.existsSync(candidate);
      if (!exists) {
        result = { path: candidate, status: "missing" };
      } else {
        const stat = fs.statSync(candidate);
        result = stat.isFile() ? { path: candidate, status: "exists" } : { path: candidate, status: "missing" };
      }
    } catch (error) {
      result = { path: candidate, status: "fs-error", error };
    }
    fileExistStatusCache.set(candidate, result);
    return result;
  }
  export function __resetStoryExistenceCacheForTests(): void {
    fileExistStatusCache.clear();
  }
- Aggregated existence with explicit fs-error status (REQ-FILE-EXISTENCE, REQ-ERROR-HANDLING):
  export function getStoryExistence(candidates: string[]): StoryExistenceResult {
    let firstFsError: StoryPathCheckResult | undefined;
    for (const candidate of candidates) {
      const res = checkSingleCandidate(candidate);
      if (res.status === "exists") {
        return { candidates, status: "exists", matchedPath: res.path };
      }
      if (res.status === "fs-error" && !firstFsError) {
        firstFsError = res;
      }
    }
    if (firstFsError) {
      return { candidates, status: "fs-error", error: firstFsError.error };
    }
    return { candidates, status: "missing" };
  }
  export function storyExists(paths: string[]): boolean {
    const result = getStoryExistence(paths);
    return result.status === "exists";
  }
- Project boundary enforcement (REQ-PROJECT-BOUNDARY):
  export function enforceProjectBoundary(candidate: string, cwd: string): ProjectBoundaryCheckResult {
    const normalizedCwd = path.resolve(cwd);
    const normalizedCandidate = path.resolve(candidate);
    const isWithinProject =
      normalizedCandidate === normalizedCwd ||
      normalizedCandidate.startsWith(normalizedCwd + path.sep);
    return { candidate: normalizedCandidate, isWithinProject };
  }
- Extension validation enforcing .story.md by default (Core Functionality / REQ-SECURITY-VALIDATION):
  export function hasValidExtension(p: string): boolean {
    return p.endsWith(".story.md");
  }

